typedef double (*FunctionPtr)(double);

double simpson_integration_impl(FunctionPtr f, double a, double b, int N) {
    double h = (b - a) / N;
    double sum = f(a) + f(b);

    for (int i = 1; i < N; i++) {
        double x = a + i * h;
        sum += 2 * f(x);
    }

    return (h / 2.0) * sum;
}

double simpson_integration(FunctionPtr f, double a, double b, int N) {
    if (N % 2 != 0) {
        // N should be even for Simpson's rule
        N = N + 1;
    }

    double h = (b - a) / N;
    double sum = 0.0;

    // Apply Simpson's rule formula
    // Composite Simpson's Rule: (h/3)[f(x0) + 4f(x1) + 2f(x2) + 4f(x3) + ... + f(xn)]
    // where points are equally spaced with step h

    for (int i = 0; i <= N; i++) {
        double x_i = a + i * h;
        double coeff = 1.0;

        if (i == 0 || i == N) {
            // f(x0) and f(xn) terms
            coeff = 1.0;
        } else if (i % 2 == 0) {
            // Even index (not 0 or N)
            coeff = 2.0;
        } else {
            // Odd index
            coeff = 4.0;
        }

        // Simpson's rule uses coefficients 1, 4, 2 pattern
        sum += coeff * f(x_i);
    }

    return (h / 3.0) * sum;
}

double simpson_integration(FunctionPtr f, double a, double b, int N) {
    if (N % 2 != 0) {
        // N should be even for Simpson's rule
        N = N + 1;
    }

    double h = (b - a) / N;
    double sum = f(a) + f(b);  // First and last points

    for (int i = 1; i < N; i++) {
        double x_i = a + i * h;
        if (i % 2 == 0) {
            sum += 2.0 * f(x_i);
        } else {
            sum += 4.0 * f(x_i);
        }
    }

    // Apply Simpson's rule: (h/3)[f(x0) + 4f(x1) + 2f(x2) + 4f(x3) + 2f(x4) + ... + f(xn)]
    return (h / 3.0) * sum;
}

